6	/// Returns the multiplier for how many query terms the block's declared name contains, from 1.0 to 3.0.
7	///
8	/// The name is the head of the block: its signature, or without one its first line that is not a comment or a
9	/// decorator, cut at the first `(`, `<`, `{`, `=` or `:`. So parameters, return types and the body do not count. In a
10	/// Rust file the parentheses of a restricted visibility (`pub(crate)`) do not cut the head. The
11	/// head is tokenized like a document, and the multiplier is `round6(1 + 2 * matched / query_terms.len())`, where
12	/// `matched` counts the query terms, repeats included, that the head contains. Returns 1.0 when `query_terms` is empty.
13	///
14	/// A body can mention every query word without the block being about them; a name that holds them says what it is.
15	///
16	/// # Examples
17	///
18	/// ```
19	/// use camino::Utf8PathBuf;
20	/// use monokl::rank::name_match_boost;
21	/// use monokl::types::{CodeBlock, SymbolKind};
22	///
23	/// let block = CodeBlock {
24	///     file: Utf8PathBuf::from("src/a.ts"),
25	///     line_start: 1,
26	///     line_end: 3,
27	///     node_kind: SymbolKind::Function,
28	///     code: String::new(),
29	///     symbol_signature: Some("function mergeConfig(a: Config, b: Config)".to_string()),
30	///     matched_lines: Vec::new(),
31	///     parent: None,
32	/// };
33	/// assert_eq!(name_match_boost(&block, &["merge", "config", "deep", "copy"]), 2.0);
34	/// ```
35	pub fn name_match_boost(block: &CodeBlock, query_terms: &[&str]) -> f64 {
36	    if query_terms.is_empty() {
37	        return 1.0;
38	    }
39	    let text = block.symbol_signature.as_deref().unwrap_or(&block.code);
40	    let line = text.lines().map(str::trim).find(|line| !is_comment_or_decorator(line)).unwrap_or_default();
41	    let name_tokens = if Language::of(&block.file) == Some(Language::Rust) {
42	        tokenize_source(&unrestricted(line))
43	    } else {
44	        tokenize_source(head_of(line))
45	    };
46	    let matched = query_terms.iter().filter(|term| name_tokens.iter().any(|token| token == *term)).count();
47	    round6(1.0 + 2.0 * as_f64(matched) / as_f64(query_terms.len()))
48	}
49	
50	fn head_of(line: &str) -> &str {
51	    line.split(['(', '<', '{', '=', ':']).next().unwrap_or_default()
52	}
53	
54	/// The head of a Rust declaration line with a restricted visibility (`pub(crate)`, `pub(super)`, `pub(in path)`) read as
55	/// a plain `pub`, whose `(` would otherwise end the head before the name. The other modifiers (`async`, `const`,
56	/// `unsafe`, `extern "C"`, `default`) hold no cut character and stay in the head.
57	fn unrestricted(line: &str) -> String {
58	    let restriction = line
59	        .strip_prefix("pub")
60	        .map(str::trim_start)
61	        .filter(|rest| rest.starts_with('('))
62	        .and_then(|rest| rest.split_once(')'));
63	    match restriction {
64	        Some((_, rest)) => format!("pub {}", head_of(rest)),
65	        None => head_of(line).to_owned(),
66	    }
67	}
68	
69	/// Whether a trimmed line carries no declaration: it is blank, a comment or comment continuation, or a decorator.
70	fn is_comment_or_decorator(line: &str) -> bool {
71	    line.is_empty()
72	        || line.starts_with("//")
73	        || line.starts_with("/*")
74	        || line.starts_with('*')
75	        || line.starts_with('@')
76	}
77	
78	/// Returns the score multiplier for a block's symbol kind.
79	///
80	/// Callable units rank highest, then type definitions, then bindings; `Other` ranks lowest.
81	///
82	/// # Examples
83	///
84	/// ```
85	/// use monokl::rank::node_type_boost;
86	/// use monokl::types::SymbolKind;
87	///
88	/// assert_eq!(node_type_boost(SymbolKind::Function), 1.5);
89	/// assert_eq!(node_type_boost(SymbolKind::Other), 0.7);
90	/// ```
91	pub fn node_type_boost(kind: SymbolKind) -> f64 {
92	    match kind {
93	        SymbolKind::Function => 1.5,
94	        SymbolKind::Class | SymbolKind::Method | SymbolKind::Constructor => 1.4,
95	        SymbolKind::Interface | SymbolKind::Struct => 1.3,
96	        SymbolKind::TypeAlias | SymbolKind::Enum => 1.2,
97	        SymbolKind::Variable | SymbolKind::Impl => 1.1,
98	        SymbolKind::Property | SymbolKind::Field | SymbolKind::Macro => 1.0,
99	        SymbolKind::Module => 0.9,
100	        SymbolKind::Other => 0.7,
101	    }
102	}
