25	/// from measurements of a whole `monokl search` over one generated file: at 3.4 MB it takes 40 ms and peaks at 94 MB of
26	/// resident memory, about 28 bytes per source byte. A file twice that long is generated data, not code a search is for,
27	/// and what it would cost is no longer small.
28	pub(super) const MAX_PARSED_SOURCE_LEN: usize = 4 << 20;
29	
30	/// The deepest nesting parsed, in levels of brackets or the equivalent in other nesting (see [`nesting::peak_cost`]).
31	///
32	/// 65,536 units (four per level) is what the fixed parse stack holds with a factor of two and a half to spare in the
33	/// worst case measured; see [`PARSE_STACK_BYTES`](crate::analysis::parse_stack::PARSE_STACK_BYTES). Ordinary code nests
34	/// a few dozen levels. A file over this is reported as too deep instead of parsed.
35	pub(super) const MAX_NESTING_LEVELS: usize = 16_384;
36	
37	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
38	#[derive(Debug, Default)]
39	pub(super) struct Extraction {
40	    pub(super) blocks: Vec<CodeBlock>,
41	    pub(super) had_parse_errors: bool,
42	    pub(super) degradation: Option<Degradation>,
43	}
44	
45	impl Extraction {
46	    /// The result for a file that could not be analyzed: no data, flagged as having errors and the reason.
47	    fn degraded(degradation: Degradation) -> Self {
48	        Self { had_parse_errors: true, degradation: Some(degradation), ..Self::default() }
49	    }
50	}
51	
52	/// Extracts the blocks of `source`.
53	///
54	/// A file too long or nested too deeply for the parse stack is [`Extraction::degraded`] without being parsed, and so is
55	/// one whose parse or extraction panics. The scan that rejects the nesting is linear in the length, and the parse runs
56	/// on a stack of one fixed size, so what a file can cost is bounded by these two limits and not by its contents.
57	pub(super) fn extract(path: &Utf8Path, source: &str) -> Extraction {
58	    if source.len() > MAX_PARSED_SOURCE_LEN {
59	        return Extraction::degraded(Degradation::TooLarge { bytes: source.len(), cap: MAX_PARSED_SOURCE_LEN });
60	    }
61	    let syntax = Syntax::TypeScript { jsx: source_type_for(path).is_jsx() };
62	    if let Err(degradation) = nesting::check(source, syntax, MAX_NESTING_LEVELS) {
63	        return Extraction::degraded(degradation);
64	    }
65	    on_parse_stack(|| parse_and_extract(path, source)).unwrap_or_else(Extraction::degraded)
66	}
67	
68	/// Parses and extracts on the calling thread, for a test that supplies its own stack.
69	#[cfg(all(test, feature = "lang-rust"))]
70	pub(super) fn parse_here(path: &Utf8Path, source: &str) {
71	    drop(parse_and_extract(path, source));
72	}
73	
74	/// JavaScript files may hold JSX whatever their extension; TypeScript files only in `.tsx`, since `<T>x` is a cast
75	/// elsewhere.
76	fn source_type_for(path: &Utf8Path) -> SourceType {
77	    let source_type = SourceType::from_path(path.as_std_path()).unwrap_or_else(|_| SourceType::ts());
78	    if source_type.is_javascript() { source_type.with_jsx(true) } else { source_type }
79	}
80	
81	fn parse_and_extract(path: &Utf8Path, source: &str) -> Extraction {
82	    let allocator = Allocator::default();
83	    // Parentheses carry no meaning here and a `ParenthesizedExpression` node would only add a level to every walk.
84	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
85	    let parsed = Parser::new(&allocator, source, source_type_for(path)).with_options(options).parse();
86	    // The recovered program is still used below, so record the diagnostics rather than discarding the parse.
87	    let had_parse_errors = parsed.fatal_error || !parsed.diagnostics.is_empty();
88	
89	    let mut extractor = Extractor { path, source, lines: LineIndex::new(source), out: Extraction::default() };
90	    for statement in &parsed.program.body {
91	        extractor.statement(statement);
92	    }
93	    Extraction { had_parse_errors, ..extractor.out }
94	}
95	
96	/// Maps byte offsets to 1-based line numbers.
97	struct LineIndex {
98	    newlines: Vec<usize>,
99	}
100	
101	impl LineIndex {
102	    fn new(source: &str) -> Self {
103	        Self { newlines: source.bytes().enumerate().filter(|&(_, byte)| byte == b'\n').map(|(i, _)| i).collect() }
104	    }
105	
106	    fn line(&self, offset: u32) -> usize {
107	        self.newlines.partition_point(|&newline| newline < offset as usize) + 1
108	    }
109	}
110	
111	struct Extractor<'s> {
112	    path: &'s Utf8Path,
113	    source: &'s str,
114	    lines: LineIndex,
115	    out: Extraction,
116	}
117	
118	impl Extractor<'_> {
119	    fn text(&self, span: Span) -> &str {
120	        self.source.get(span.start as usize..span.end as usize).unwrap_or_default()
121	    }
122	
123	    fn statement(&mut self, statement: &Statement<'_>) {
124	        self.block(statement);
125	        self.member_blocks(statement);
126	    }
127	
128	    /// The function's text up to its body, on one line: `function f(a: A): B`.
129	    fn function_signature(&self, function: &Function<'_>) -> String {
130	        let end = function.body.as_ref().map_or(function.span.end, |body| body.span.start);
131	        self.signature_text(Span::new(function.span.start, end))
132	    }
133	
134	    /// The text of `span` on one line, without a trailing `;`.
135	    fn signature_text(&self, span: Span) -> String {
136	        self.text(span).split_whitespace().collect::<Vec<_>>().join(" ").trim_end_matches(';').trim_end().to_owned()
137	    }
138	
139	    fn block(&mut self, statement: &Statement<'_>) {
140	        let Some(node_kind) = statement_kind(statement) else { return };
141	        if matches!(statement, Statement::ImportDeclaration(_)) {
142	            return;
143	        }
144	        let symbol_signature = match (node_kind, statement_function(statement)) {
145	            (SymbolKind::Function, Some(function)) => Some(self.function_signature(function)),
146	            _ => None,
147	        };
148	        self.push_block(statement.span(), node_kind, symbol_signature, None);
149	    }
150	
151	    /// Pushes a block over `span`, unless it holds nothing but whitespace.
152	    fn push_block(
153	        &mut self,
154	        span: Span,
155	        node_kind: SymbolKind,
156	        symbol_signature: Option<String>,
157	        parent: Option<ParentContext>,
158	    ) {
159	        let code = self.text(span);
160	        if code.trim().is_empty() {
161	            return;
162	        }
163	        let block = CodeBlock {
164	            file: self.path.to_owned(),
165	            line_start: self.lines.line(span.start),
166	            line_end: self.lines.line(span.end),
167	            node_kind,
168	            code: code.to_owned(),
169	            symbol_signature,
170	            matched_lines: Vec::new(),
171	            parent,
172	        };
173	        self.out.blocks.push(block);
174	    }
175	
176	    /// Pushes a block for each long member of the named class or object literal that a top-level or exported statement
177	    /// holds, after the statement's own block. An anonymous class has no name to give its members as a parent, so it
178	    /// gets none.
179	    fn member_blocks(&mut self, statement: &Statement<'_>) {
180	        if let Some(class) = statement_class(statement) {
181	            self.class_member_blocks(class);
182	        }
183	        for (parent, object) in Self::statement_objects(statement) {
184	            for property in &object.properties {
185	                match property {
186	                    ObjectPropertyKind::ObjectProperty(property) => self.object_property_block(property, &parent),
187	                    ObjectPropertyKind::SpreadProperty(_) => {}
188	                }
189	            }
190	        }
191	    }
192	
193	    /// The object literals a top-level or exported statement binds to a name, each with the parent its members get: the
194	    /// declarator's name for `const api = { ... }`, `default` for `export default { ... }`.
195	    fn statement_objects<'a, 'b>(statement: &'b Statement<'a>) -> Vec<(ParentContext, &'b ObjectExpression<'a>)> {
196	        let declaration = match statement {
197	            Statement::VariableDeclaration(declaration) => Some(&**declaration),
198	            Statement::ExportDeclaration(export) => match &export.declaration {
199	                Declaration::VariableDeclaration(declaration) => Some(&**declaration),
200	                _ => None,
201	            },
202	            _ => None,
203	        };
204	        if let Some(declaration) = declaration {
205	            return declaration
206	                .declarations
207	                .iter()
208	                .filter_map(|declarator| {
209	                    let BindingPattern::BindingIdentifier(id) = &declarator.id else { return None };
210	                    let object = object_literal(declarator.init.as_ref()?)?;
211	                    let parent = ParentContext { kind: SymbolKind::Variable, name: id.name.as_str().to_owned() };
212	                    Some((parent, object))
213	                })
214	                .collect();
215	        }
216	        let Statement::ExportDefaultDeclaration(export) = statement else { return Vec::new() };
217	        let Some(object) = export.declaration.as_expression().and_then(object_literal) else { return Vec::new() };
218	        let parent = ParentContext { kind: SymbolKind::Other, name: "default".to_owned() };
219	        vec![(parent, object)]
220	    }
221	
222	    /// A method, constructor or function-valued property of a named class.
223	    fn class_member_blocks(&mut self, class: &Class<'_>) {
224	        let Some(id) = &class.id else { return };
225	        let parent = ParentContext { kind: SymbolKind::Class, name: id.name.as_str().to_owned() };
226	        for element in &class.body.body {
227	            match element {
228	                ClassElement::MethodDefinition(method) => self.method_block(method, &parent),
229	                ClassElement::PropertyDefinition(property) => self.property_block(property, &parent),
230	                ClassElement::StaticBlock(_)
231	                | ClassElement::AccessorProperty(_)
232	                | ClassElement::TSIndexSignature(_) => {}
233	            }
234	        }
235	    }
236	
237	    /// A method with a body: `async f(a: A): B { ... }`. Getters and setters are methods; a signature without a body
238	    /// (an overload or an abstract method) is not.
239	    fn method_block(&mut self, method: &MethodDefinition<'_>, parent: &ParentContext) {
240	        let Some(body) = &method.value.body else { return };
241	        let node_kind = match method.kind {
242	            MethodDefinitionKind::Constructor => SymbolKind::Constructor,
243	            MethodDefinitionKind::Method | MethodDefinitionKind::Get | MethodDefinitionKind::Set => SymbolKind::Method,
244	        };
245	        let head = Span::new(method.decorators.last().map_or(method.span.start, |d| d.span.end), body.span.start);
246	        let signature = self.signature_text(head);
247	        self.member_block(method.span, node_kind, signature, parent);
248	    }
249	
250	    /// A property holding an arrow or function expression: `handle = async (req) => { ... }`. Any other value is data,
251	    /// which the class block shows well enough.
252	    fn property_block(&mut self, property: &PropertyDefinition<'_>, parent: &ParentContext) {
253	        let Some(body_start) = property.value.as_ref().and_then(function_body_start) else { return };
254	        let head = Span::new(property.decorators.last().map_or(property.span.start, |d| d.span.end), body_start);
255	        let signature = self.signature_text(head);
256	        self.member_block(property.span, SymbolKind::Property, signature, parent);
257	    }
258	
259	    /// An object property that is a method (`async f() { ... }`, a getter or a setter) or holds an arrow or function
260	    /// expression (`f: () => { ... }`). Any other value is data, which the object's block shows well enough.
261	    fn object_property_block(&mut self, property: &ObjectProperty<'_>, parent: &ParentContext) {
262	        let Some(body_start) = function_body_start(&property.value) else { return };
263	        let node_kind = if property.method || property.kind != PropertyKind::Init {
264	            SymbolKind::Method
265	        } else {
266	            SymbolKind::Property
267	        };
268	        let signature = self.signature_text(Span::new(property.span.start, body_start));
269	        self.member_block(property.span, node_kind, signature, parent);
270	    }
271	
272	    fn member_block(&mut self, span: Span, node_kind: SymbolKind, signature: String, parent: &ParentContext) {
273	        let lines = self.lines.line(span.end) - self.lines.line(span.start) + 1;
274	        if lines >= MIN_MEMBER_LINES {
275	            self.push_block(span, node_kind, Some(signature), Some(parent.clone()));
276	        }
277	    }
278	}
279	
280	/// The kind of block a top-level statement makes, or `None` when it is not one.
281	fn statement_kind(statement: &Statement<'_>) -> Option<SymbolKind> {
282	    match statement {
283	        Statement::FunctionDeclaration(_) => Some(SymbolKind::Function),
284	        Statement::ClassDeclaration(_) => Some(SymbolKind::Class),
285	        Statement::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
286	        Statement::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
287	        Statement::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
288	        Statement::VariableDeclaration(_) => Some(SymbolKind::Variable),
289	        Statement::ExportDeclaration(export) => {
290	            Some(declaration_kind(&export.declaration).unwrap_or(SymbolKind::Other))
291	        }
292	        Statement::ExportDefaultDeclaration(export) => Some(match &export.declaration {
293	            ExportDefaultDeclarationKind::FunctionDeclaration(_) => SymbolKind::Function,
294	            ExportDefaultDeclarationKind::ClassDeclaration(_) => SymbolKind::Class,
295	            ExportDefaultDeclarationKind::TSInterfaceDeclaration(_) => SymbolKind::Interface,
296	            _ => SymbolKind::Other,
297	        }),
298	        Statement::ImportDeclaration(_)
299	        | Statement::ExportNamedDeclaration(_)
300	        | Statement::ExportFromDeclaration(_)
301	        | Statement::ExportAllDeclaration(_) => Some(SymbolKind::Other),
302	        _ => None,
303	    }
304	}
305	
306	fn declaration_kind(decl: &Declaration<'_>) -> Option<SymbolKind> {
307	    match decl {
308	        Declaration::FunctionDeclaration(_) => Some(SymbolKind::Function),
309	        Declaration::ClassDeclaration(_) => Some(SymbolKind::Class),
310	        Declaration::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
311	        Declaration::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
312	        Declaration::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
313	        Declaration::VariableDeclaration(_) => Some(SymbolKind::Variable),
314	        Declaration::TSExternalModuleDeclaration(_)
315	        | Declaration::TSNamespaceDeclaration(_)
316	        | Declaration::TSGlobalDeclaration(_)
317	        | Declaration::TSImportEqualsDeclaration(_) => None,
318	    }
319	}
320	
321	/// Where the body of an arrow function or function expression starts; `None` for any other expression and for a
322	/// function without a body.
323	fn function_body_start(expression: &Expression<'_>) -> Option<u32> {
324	    match expression {
325	        Expression::ArrowFunctionExpression(arrow) => Some(arrow.body.span().start),
326	        Expression::FunctionExpression(function) => function.body.as_ref().map(|body| body.span.start),
327	        _ => None,
328	    }
329	}
330	
331	/// The object literal an expression is, looking through parentheses, `as`, `satisfies` and `!`.
332	fn object_literal<'a, 'b>(expression: &'b Expression<'a>) -> Option<&'b ObjectExpression<'a>> {
333	    match expression {
334	        Expression::ObjectExpression(object) => Some(object),
335	        Expression::ParenthesizedExpression(inner) => object_literal(&inner.expression),
336	        Expression::TSAsExpression(inner) => object_literal(&inner.expression),
337	        Expression::TSSatisfiesExpression(inner) => object_literal(&inner.expression),
338	        Expression::TSNonNullExpression(inner) => object_literal(&inner.expression),
339	        _ => None,
340	    }
341	}
342	
343	/// The class a statement declares, directly or through `export` or `export default`.
344	fn statement_class<'a, 'b>(statement: &'b Statement<'a>) -> Option<&'b Class<'a>> {
345	    match statement {
346	        Statement::ClassDeclaration(class) => Some(class),
347	        Statement::ExportDeclaration(export) => match &export.declaration {
348	            Declaration::ClassDeclaration(class) => Some(class),
349	            _ => None,
350	        },
351	        Statement::ExportDefaultDeclaration(export) => match &export.declaration {
352	            ExportDefaultDeclarationKind::ClassDeclaration(class) => Some(class),
353	            _ => None,
354	        },
355	        _ => None,
356	    }
357	}
358	
359	/// The function a statement declares, directly or through `export`.
360	fn statement_function<'a, 'b>(statement: &'b Statement<'a>) -> Option<&'b Function<'a>> {
361	    match statement {
362	        Statement::FunctionDeclaration(function) => Some(function),
363	        Statement::ExportDeclaration(export) => match &export.declaration {
364	            Declaration::FunctionDeclaration(function) => Some(function),
365	            _ => None,
366	        },
367	        _ => None,
368	    }
369	}
370	
