372	mod tests {
373	    use rstest::rstest;
374	
375	    use super::*;
376	
377	    #[test]
378	    fn a_parenthesized_default_export_has_no_function_block() {
379	        let extraction = extract(Utf8Path::new("a.ts"), "export default (function g() {});\n");
380	        assert!(!extraction.had_parse_errors);
381	        let blocks: Vec<_> = extraction.blocks.iter().map(|b| (b.line_start, b.line_end, b.node_kind)).collect();
382	        assert_eq!(blocks, [(1, 1, SymbolKind::Other)]);
383	    }
